head.script:
if (!WebSquare.uiplugin.popup) {
	requires("uiplugin.popup");
}

scwin.cnt = 0;

scwin.trigger1_onclick = function() {
	scwin.cnt++;
	var value = scwin.cnt % 2 ? "W" : "T";
	var options = {
		id: "popup" + scwin.cnt,
		type: "browserPopup",
		width: "800px",
		height: "600px",
		modal: false,
		resizeEvent: false,
		resizable: false
	};
	var url = "/sample/common_link/wframe_browserPopup_close_WAEA-124_(WSQ-5925)_" + value + ".xml";
	$p.openPopup(url, options);
};
